#!/usr/bin/env bash
set -Eeuo pipefail
umask 027
[[ "$EUID" -eq 0 ]] || { echo "Run as root" >&2; exit 1; }
venv=/opt/auto-photo-ingest/venv
[[ -x "$venv/bin/python" ]] || { echo "Virtual environment not found" >&2; exit 1; }
work_dir="$(mktemp -d /root/auto-photo-repair.XXXXXX)"
cleanup() { rm -rf -- "$work_dir"; }
trap cleanup EXIT
systemctl stop auto-photo-ingest.timer 2>/dev/null || true
cat > "$work_dir/package.whl.b64" <<'PAYLOAD'

PAYLOAD
base64 -d "$work_dir/package.whl.b64" > "$work_dir/auto_photo_ingest-0.2.0-py3-none-any.whl"
printf '%s  %s
' '4fd2b304637ebad07a13c0140e7f5d89b2b036cad12bd63432a92c688d3fe6ee' "$work_dir/auto_photo_ingest-0.2.0-py3-none-any.whl" | sha256sum -c -
site_dir="$($venv/bin/python -c "import sysconfig; print(sysconfig.get_paths()['purelib'])")"
$venv/bin/python - "$site_dir" <<'PY2'
from pathlib import Path
import shutil, sys
root = Path(sys.argv[1]).resolve()
for pattern in ('auto_photo_ingest', 'auto_photo_ingest-*.dist-info'):
    for path in root.glob(pattern):
        if path.parent.resolve() != root:
            raise SystemExit('Unsafe package path')
        if path.is_dir():
            shutil.rmtree(path)
        elif path.exists():
            path.unlink()
PY2
$venv/bin/python -m pip install --no-deps --force-reinstall "$work_dir/auto_photo_ingest-0.2.0-py3-none-any.whl"
$venv/bin/python -c "import auto_photo_ingest.cli, auto_photo_ingest.screening, auto_photo_ingest.worker; print('IMPORTS=OK')"
runuser -u auto-photo-ingest -- "$venv/bin/auto-photo-ingest" init --data-dir /var/lib/auto-photo-ingest
runuser -u auto-photo-ingest -- "$venv/bin/auto-photo-ingest" screen-plan --data-dir /var/lib/auto-photo-ingest
runuser -u auto-photo-ingest -- "$venv/bin/auto-photo-ingest" screen-export --data-dir /var/lib/auto-photo-ingest --output-dir /var/lib/auto-photo-ingest/screening
systemctl reset-failed auto-photo-ingest.service 2>/dev/null || true
systemctl start auto-photo-ingest.service
systemctl enable --now auto-photo-ingest.timer
printf 'REPAIR=OK
VERSION='
$venv/bin/python -c "from importlib.metadata import version; print(version('auto-photo-ingest'))"
printf 'COUNTS=
'
$venv/bin/python - <<'PY3'
import json, sqlite3
root = '/var/lib/auto-photo-ingest'
db = sqlite3.connect(root + '/catalogue.sqlite3')
print('photos:', db.execute('select count(*) from assets').fetchone()[0])
print('vehicle_groups:', db.execute('select count(*) from vehicle_candidates').fetchone()[0])
print('grouped_photos:', db.execute('select count(*) from candidate_assets').fetchone()[0])
with open(root + '/screening/summary.json', encoding='utf-8') as handle:
    print('queues:', json.load(handle))
PY3
printf 'TIMER='
systemctl is-active auto-photo-ingest.timer
